  if(m.kind==='geology'){const v=document.querySelector('input[name="sample"]:checked')?.value;ok=v==='a';feedback=ok?'Sample A selected. Its geological character and documented field context make it the strongest scientific choice.':'A useful sample needs a recorded location and field description. Select the breccia with documented context, not just the most attractive specimen.'}
  if(m.kind==='landing'){const rate=+$('land-rate').value,drift=+$('land-drift').value;ok=rate>=1&&rate<=3&&drift<1.5;feedback=ok?'Descent profile stabilized inside the simplified final-approach envelope.':'Approach is outside the training envelope. Aim for 1–3 m/s vertical descent and less than 1.5 m/s horizontal drift.'}
  if(m.kind==='emergency'){const v=document.querySelector('input[name="alarm"]:checked')?.value;ok=v==='a';feedback=ok?'Correct crew response. Identify, cross-check, communicate and then follow the applicable procedure with Mission Control.':'Do not make an unverified drastic change or ignore the warning. Identify the indication, cross-check it and communicate clearly.'}
  const fb=$('training-feedback');fb.className='training-feedback '+(ok?'pass':'retry');fb.textContent=(ok?'PASS · ':'REVIEW REQUIRED · ')+feedback;
  if(ok){trainingPassed.add(id);$('evaluate-training').textContent='MODULE PASSED ✓';$('evaluate-training').disabled=true;updateTrainingProgress();}
