const chapters=[["LIFE ON EARTH","Explore the apartment and discover Neil's early interest in flight.",apartment],["NASA HEADQUARTERS","Learn how Armstrong became a NASA astronaut.",nasa],["ASTRONAUT TRAINING","Complete six hands-on astronaut training simulations.",training],["SATURN V LAUNCH","Explore the Apollo 11 launch site.",launch],["THE MOON","Explore the lunar surface and the first moonwalk.",moon],["RETURN TO EARTH","Visit the recovery area and complete the mission.",earthReturn]];
function load(){let c=chapters[chapterIndex];const tp=$("training-progress");if(tp)tp.style.display=chapterIndex===2?"block":"none";c[2]();$("chapter-no").textContent=`CHAPTER 0${chapterIndex+1} / 06`;$("chapter").textContent=c[0];$("objective").textContent=c[1];$("hud").classList.remove("hidden");toast(c[0]);renderer.render(scene,camera)}
function advance(){$("next").classList.add("hidden");chapterDone=false;if(chapterIndex<5)chapterIndex++;load()}
function showFatalError(error){
  console.error("Apollo 11 scene error:",error);
  const panel=$("fatal-error"),message=$("fatal-message");
  if(message)message.textContent=(error&&error.message)?error.message:"An unexpected graphics error occurred. Please reload and try again.";
  if(panel)panel.classList.remove("hidden");
  $("home").classList.add("hidden");
  $("hud").classList.add("hidden");
}
$("begin").addEventListener("click",()=>{
  if(started)return;
  try{
    started=true;
    $("home").classList.add("hidden");
    load();
    if(window.matchMedia&&window.matchMedia("(pointer:fine)").matches){renderer.domElement.requestPointerLock?.();}
  }catch(error){started=false;showFatalError(error)}
});
$("fatal-retry").onclick=()=>{ $("fatal-error").classList.add("hidden");$("home").classList.remove("hidden");$("hud").classList.add("hidden"); };
$("continue").onclick=()=>{$("flight-panel").classList.add("hidden");flight=null;advance()};
$("throttle").addEventListener("input",e=>{if(flight){flight.throttle=+e.target.value;$("throttle-value").textContent=flight.throttle+"%"}});
$("ignite").onclick=()=>{if(!flight)return;flight.active=true;flight.throttle=Math.max(flight.throttle,82);$("throttle").value=flight.throttle;$("throttle-value").textContent=flight.throttle+"%";$("ignite").disabled=true;$("flight-phase").textContent="ENGINE START · LIFTOFF";toast("SATURN V · LIFTOFF SEQUENCE")};
$("stage").onclick=()=>{if(!flight)return;if(flight.altitude>=28&&!flight.stage1){flight.stage1=true;flight.stageIndex=1;flight.rocket.scale.y*=.91;$("flight-phase").textContent="S-II · SECOND STAGE";toast("S-IC FIRST STAGE JETTISONED")}else if(flight.altitude>=55&&flight.stage1&&!flight.stage2){flight.stage2=true;flight.stageIndex=2;flight.rocket.scale.y*=.94;$("flight-phase").textContent="S-IVB · THIRD STAGE";toast("S-II SECOND STAGE JETTISONED")}else toast("WAIT FOR THE NEXT STAGING MILESTONE")};
$("tli").onclick=()=>{if(!flight||!flight.orbit)return;flight.tli=true;flight.active=false;$("flight-phase").textContent="TRANS-LUNAR INJECTION · COMPLETE";$("tli").disabled=true;$("stage").disabled=true;story("JULY 16, 1969 · TRANS-LUNAR INJECTION","After roughly one and a half Earth orbits, the S-IVB third stage reignited. Columbia separated, turned around, docked with Eagle, and extracted the Lunar Module from the adapter. Apollo 11 was now on its three-day coast to the Moon. This is a simplified interactive reconstruction, not a flight-certified trajectory.","CONTINUE TO THE MOON");$("story-ok").onclick=()=>{$("dialog").classList.add("hidden");dialogue=false;nextChapter("THE MOON","Apollo 11 coasted for about three days, entered lunar orbit on July 19, and separated Eagle from Columbia on July 20.")}};
$("close").onclick=()=>{$("dialog").classList.add("hidden");dialogue=false};
$("mission-log").onclick=()=>{document.exitPointerLock?.();$("log-content").innerHTML=chapters.map((c,i)=>`<button class="chapter-link ${i===chapterIndex?"current":""}" data-chapter="${i}"><span>0${i+1}</span><b>${c[0]}</b><small>${c[1]}</small><em>OPEN →</em></button>`).join("");$("log").classList.remove("hidden")};
$("log-content").addEventListener("click",e=>{const b=e.target.closest("[data-chapter]");if(!b)return;chapterIndex=Number(b.dataset.chapter);chapterDone=false;flight=null;$("flight-panel").classList.add("hidden");$("next").classList.add("hidden");$("log").classList.add("hidden");load()});
$("log-close").onclick=()=>$("log").classList.add("hidden");
$("home-button").onclick=()=>{document.exitPointerLock?.();started=false;chapterDone=false;dialogue=false;flight=null;$("hud").classList.add("hidden");$("flight-panel").classList.add("hidden");$("home").classList.remove("hidden");$("log").classList.add("hidden");$("next").classList.add("hidden");$("dialog").classList.add("hidden")};
renderer.domElement.addEventListener("click",()=>{if(started&&!dialogue&&!chapterDone&&matchMedia("(pointer:fine)").matches&&!locked)renderer.domElement.requestPointerLock?.()});
document.addEventListener("pointerlockchange",()=>locked=document.pointerLockElement===renderer.domElement);
$("begin-bottom").onclick=()=>$("design-lab").scrollIntoView({behavior:"smooth"});document.querySelectorAll(".site-nav a").forEach(a=>a.addEventListener("click",e=>{const target=document.querySelector(a.getAttribute("href"));if(target){e.preventDefault();target.scrollIntoView({behavior:"smooth",block:"start"})}}));
const keys={},touch={};document.addEventListener("keydown",e=>{keys[e.code]=true;if(flight&&flight.active){if(e.code==="ArrowUp")flight.pitch=Math.max(-12,flight.pitch-1);if(e.code==="ArrowDown")flight.pitch=Math.min(12,flight.pitch+1);if(e.code==="ArrowLeft")flight.yaw=Math.max(-8,flight.yaw-1);if(e.code==="ArrowRight")flight.yaw=Math.min(8,flight.yaw+1);if(e.code==="KeyW"||e.code==="KeyS"){$("throttle").value=THREE.MathUtils.clamp(+$(("throttle")).value+(e.code==="KeyW"?2:-2),0,100);$("throttle").dispatchEvent(new Event("input"))}}if(e.code==="KeyE"&&near&&!dialogue&&!chapterDone)near.callback()});document.addEventListener("keyup",e=>keys[e.code]=false);
const euler=new THREE.Euler(0,0,0,"YXZ");document.addEventListener("mousemove",e=>{if(!locked||dialogue)return;euler.setFromQuaternion(camera.quaternion);euler.y-=e.movementX*.002;euler.x=THREE.MathUtils.clamp(euler.x-e.movementY*.002,-1.45,1.45);camera.quaternion.setFromEuler(euler)});
function find(){near=null;let d=2.6;for(const t of targets){let n=Math.hypot(camera.position.x-t.x,camera.position.z-t.z);if(n<d){d=n;near=t}}if(near){$("prompt").classList.remove("hidden");$("prompt-name").textContent=near.name}else $("prompt").classList.add("hidden")}
function move(dt){if(!started||dialogue||chapterDone||!$("log").classList.contains("hidden"))return;if(flight){updateFlight(dt);return;}let f=new THREE.Vector3();camera.getWorldDirection(f);f.y=0;f.normalize();let r=new THREE.Vector3().crossVectors(f,new THREE.Vector3(0,1,0)).normalize();let v=new THREE.Vector3();if(keys.KeyW||keys.ArrowUp||touch.KeyW)v.add(f);if(keys.KeyS||keys.ArrowDown||touch.KeyS)v.sub(f);if(keys.KeyD||keys.ArrowRight||touch.KeyD)v.add(r);if(keys.KeyA||keys.ArrowLeft||touch.KeyA)v.sub(r);if(v.lengthSq()){v.normalize().multiplyScalar((keys.ShiftLeft?5:3.2)*dt);camera.position.x=THREE.MathUtils.clamp(camera.position.x+v.x,-10.5,10.5);camera.position.z=THREE.MathUtils.clamp(camera.position.z+v.z,-10.5,10.5)}camera.position.y=1.65;find()}
document.querySelectorAll("[data-key]").forEach(b=>{let k=b.dataset.key;b.onpointerdown=e=>{e.preventDefault();touch[k]=true};["pointerup","pointercancel","pointerleave"].forEach(ev=>b.addEventListener(ev,()=>touch[k]=false))});$("use").onclick=()=>near?.callback();
let look=null;$("look").onpointerdown=e=>{look=[e.clientX,e.clientY];$("look").setPointerCapture(e.pointerId)};$("look").onpointermove=e=>{if(!look)return;let dx=e.clientX-look[0],dy=e.clientY-look[1];look=[e.clientX,e.clientY];euler.setFromQuaternion(camera.quaternion);euler.y-=dx*.006;euler.x=THREE.MathUtils.clamp(euler.x-dy*.006,-1.4,1.4);camera.quaternion.setFromEuler(euler)};$("look").onpointerup=()=>look=null;
let toastTimer;function toast(t){$("toast").textContent=t;$("toast").classList.remove("hidden");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").classList.add("hidden"),1800)}
const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);move(Math.min(clock.getDelta(),.04));renderer.render(scene,camera)}
// Keep the opening screen responsive; build the first 3D chapter only after Start is pressed.
animate();addEventListener("resize",()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
// Recover gracefully if the browser suspends rendering while the tab is in the background.
document.addEventListener("visibilitychange",()=>{if(!document.hidden)clock.getDelta()});
